package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AResultAttemptRepository implements A2AResultAttemptRepository { private final A2AResultAttemptDao dao; private final A2APersistenceConverter c; public MybatisA2AResultAttemptRepository(A2AResultAttemptDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2AResultAttempt save(A2AResultAttempt v){if(dao.insert(c.toPo(v))!=1)throw new IllegalStateException("A2A_RESULT_ATTEMPT_APPEND_FAILED");return v;} public List<A2AResultAttempt> findByRequest(String t,String id,int n){return dao.findByRequest(t,id,cap(n)).stream().map(c::toDomain).toList();} public String mode(){return "MYBATIS";} private int cap(int n){return Math.max(1,Math.min(n,1000));} }
